mapper.delete:
/* OrderCommonCsMapper.deleteFileShareFile : FileShareFile Delete */
DELETE FROM TB_COM_FILE_SHARE_FILE
WHERE REFERENCE_NO_ID = #{referenceNoId}
AND SEQ_NO = #{seqNo}

/* OrderCommonCsMapper.deleteFileShareFile : FileShare Delete */
DELETE FROM TB_COM_FILE_SHARE
WHERE REFERENCE_NO_ID = #{referenceNoId}

mapper.insert:
	/* OrderCommonCsMapper.insertFileShare : 파일등록 */

	SELECT ISNULL(MAX(REFERENCE_NO_ID), 0) + 1 
  	FROM TB_COM_FILE_SHARE


	INSERT INTO TB_COM_FILE_SHARE(			
		REFERENCE_NO_ID
		,ENT_CODE
		,ENT_BUSINESS_CODE
		,SOLUTION
		,SUBJECT
		,MEMO
		,FUNC_TYPE
		,FUNC_SUB_TYPE
		,FUNC_JOB_NO
		,FUNC_REFERENCE_NO
		,FILE_DOC_TYPE
		,FILE_NAME
		,FILE_EXT
		,FILE_SIZE
		,FILE_NAME_REMOTE
		,FILE_PATH_REMOTE
		,SHARE_YN
		,MEMO_DATE
		,FS_SERVER_TYPE
		,REGISTER_USER_ID
		,REGISTER_DATE_TIME
		,UPDATE_USER_ID
		,UPDATE_DATE_TIME
	)	
	VALUES(
		#{referenceNoId}
		,#{entCode}
		,#{entBusinessCode}
		,#{solution}
		,#{subject}
		,#{memo}
		,#{funcType}
		,#{funcSubType}
		,#{funcJobNo}
		,#{funcReferenceNo}
		,#{fileDocType}
		,#{fileName}
		,#{fileExt}
		,#{fileSize}
		,#{fileNameRemote}
		,#{filePathRemote}
		,#{shareYn}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,'WEB'
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,#{registerUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)


		INSERT INTO TB_COM_FILE_SHARE_FILE(
			REFERENCE_NO_ID
			,SEQ_NO
			,FILE_DOC_TYPE
			,FILE_NAME
			,FILE_SIZE
			,FILE_NAME_REMOTE
			,FILE_PATH_REMOTE
		)VALUES

		(	
			#{referenceNoId}
		  , #{item.seqNo}
		  , #{item.fileDocType}
		  , #{item.fileName}
		  , #{item.fileSize}
		  , #{item.fileNameRemote}
		  , #{item.filePathRemote}
		)

		;

/* OrderCommonCsMapper.insertFileShareFile : 파일등록 */

	INSERT INTO TB_COM_FILE_SHARE_FILE(
		REFERENCE_NO_ID
		,SEQ_NO
		,FILE_DOC_TYPE
		,FILE_NAME
		,FILE_SIZE
		,FILE_NAME_REMOTE
		,FILE_PATH_REMOTE
	)VALUES

	(	
		#{referenceNoId}
	  , #{item.seqNo}
	  , #{item.fileDocType}
	  , #{item.fileName}
	  , #{item.fileSize}
	  , #{item.fileNameRemote}
	  , #{item.filePathRemote}
	)

	;

mapper.update:
		UPDATE TB_COM_FILE_SHARE SET
			SUBJECT = #{subject}
			,MEMO = #{memo}

			,FILE_DOC_TYPE = ''
			,FILE_NAME = ''
			,FILE_EXT = ''
			,FILE_SIZE = ''
			,FILE_NAME_REMOTE = ''
			,FILE_PATH_REMOTE = ''

		WHERE REFERENCE_NO_ID = #{referenceNoId}
		;

    	IF @@ROWCOUNT = 0

    	INSERT INTO TB_COM_FILE_SHARE(			
			REFERENCE_NO_ID
			,ENT_CODE
			,ENT_BUSINESS_CODE
			,SOLUTION
			,SUBJECT
			,MEMO
			,FUNC_TYPE
			,FUNC_SUB_TYPE
			,FUNC_JOB_NO
			,FUNC_REFERENCE_NO
			,FILE_DOC_TYPE
			,FILE_NAME
			,FILE_EXT
			,FILE_SIZE
			,FILE_NAME_REMOTE
			,FILE_PATH_REMOTE
			,SHARE_YN
			,MEMO_DATE
			,FS_SERVER_TYPE
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
			,UPDATE_USER_ID
			,UPDATE_DATE_TIME
		)	
		VALUES(
			(SELECT ISNULL(MAX(REFERENCE_NO_ID), 0) + 1 FROM TB_COM_FILE_SHARE)
			,#{entCode}
			,#{entBusinessCode}
			,#{solution}
			,#{subject}
			,#{memo}
			,#{funcType}
			,#{funcSubType}
			,#{funcJobNo}
			,#{funcReferenceNo}
			,#{fileDocType}
			,#{fileName}
			,#{fileExt}
			,#{fileSize}
			,#{fileNameRemote}
			,#{filePathRemote}
			,#{shareYn}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,'WEB'
			,#{registerUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,#{registerUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
		)
